#[derive(Debug, Clone)]
#[allow(non_camel_case_types)]
#[repr(C)]
pub struct EVENT_PARAM {
    state_map_id: u32,
    owner_id: u32,
    bonfire_id: u16,
    resource_type: u8,
    boot_type: u8,
    owner_type: u8,
    bits_d: u8,
    a_reserved1: [u8; 2],
}

impl ParamDef for EVENT_PARAM {
    const NAME: &str = "EVENT_PARAM";
}

impl EVENT_PARAM {
    pub fn state_map_id(&self) -> u32 {
        self.state_map_id
    }

    pub fn set_state_map_id(&mut self, value: u32) {
        self.state_map_id = value;
    }

    pub fn owner_id(&self) -> u32 {
        self.owner_id
    }

    pub fn set_owner_id(&mut self, value: u32) {
        self.owner_id = value;
    }

    pub fn bonfire_id(&self) -> u16 {
        self.bonfire_id
    }

    pub fn set_bonfire_id(&mut self, value: u16) {
        self.bonfire_id = value;
    }

    pub fn resource_type(&self) -> u8 {
        self.resource_type
    }

    pub fn set_resource_type(&mut self, value: u8) {
        self.resource_type = value;
    }

    pub fn boot_type(&self) -> u8 {
        self.boot_type
    }

    pub fn set_boot_type(&mut self, value: u8) {
        self.boot_type = value;
    }

    pub fn owner_type(&self) -> u8 {
        self.owner_type
    }

    pub fn set_owner_type(&mut self, value: u8) {
        self.owner_type = value;
    }

    #[allow(clippy::identity_op)]
    pub fn b_group_condition_sync(&self) -> bool {
        self.bits_d & (1 << 0) != 0
    }

    #[allow(clippy::identity_op)]
    pub fn set_b_group_condition_sync(&mut self, value: bool) {
        self.bits_d = (self.bits_d & !(1 << 0)) | (u8::from(value) << 0);
    }

    #[allow(clippy::identity_op)]
    pub fn b_player_dead_playing(&self) -> bool {
        self.bits_d & (1 << 1) != 0
    }

    #[allow(clippy::identity_op)]
    pub fn set_b_player_dead_playing(&mut self, value: bool) {
        self.bits_d = (self.bits_d & !(1 << 1)) | (u8::from(value) << 1);
    }

    #[allow(clippy::identity_op)]
    pub fn b_demo_playing(&self) -> bool {
        self.bits_d & (1 << 2) != 0
    }

    #[allow(clippy::identity_op)]
    pub fn set_b_demo_playing(&mut self, value: bool) {
        self.bits_d = (self.bits_d & !(1 << 2)) | (u8::from(value) << 2);
    }
}

